import 'package:flutter/material.dart';

class AppThemeState {
  final ThemeMode themeMode;
  final Color accentColor;

  /// Light color scheme generated by `org.rde.Theme`, when available.
  final ColorScheme? lightScheme;

  /// Dark color scheme generated by `org.rde.Theme`, when available.
  final ColorScheme? darkScheme;

  const AppThemeState({
    required this.themeMode,
    required this.accentColor,
    this.lightScheme,
    this.darkScheme,
  });

  factory AppThemeState.initial() {
    return const AppThemeState(
      themeMode: ThemeMode.system,
      accentColor: Color(0xFF6750A4),
    );
  }

  AppThemeState copyWith({
    ThemeMode? themeMode,
    Color? accentColor,
    ColorScheme? lightScheme,
    ColorScheme? darkScheme,
    bool clearSchemes = false,
  }) {
    return AppThemeState(
      themeMode: themeMode ?? this.themeMode,
      accentColor: accentColor ?? this.accentColor,
      lightScheme: clearSchemes ? null : (lightScheme ?? this.lightScheme),
      darkScheme: clearSchemes ? null : (darkScheme ?? this.darkScheme),
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AppThemeState &&
          runtimeType == other.runtimeType &&
          themeMode == other.themeMode &&
          accentColor == other.accentColor &&
          lightScheme == other.lightScheme &&
          darkScheme == other.darkScheme;

  @override
  int get hashCode =>
      themeMode.hashCode ^
      accentColor.hashCode ^
      lightScheme.hashCode ^
      darkScheme.hashCode;
}
